<?php
namespace Tests\Feature;
use Tests\TestCase;
use Tests\Support\AcademicFixture;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\DB;
use App\Models\User;
use App\Services\{TermWorkflowService,EnrollmentService,WaitingListService};
class ReferenceWorkflowTest extends TestCase {
 use RefreshDatabase,AcademicFixture;
 private array $f;
 protected function setUp():void{parent::setUp();$this->f=$this->fixture();$this->actingAs($this->f['registrar']);}
 private function open():void{DB::table('periods')->where('id',$this->f['period'])->update(['academic_year'=>'2026-2027','start_date'=>'2026-11-01','end_date'=>'2027-03-01']);app(TermWorkflowService::class)->activate($this->f['period']);}
 private function accept():int{$id=app(EnrollmentService::class)->propose($this->f['student'],$this->f['period'],[$this->f['offering']]);$this->actingAs($this->f['user']);app(EnrollmentService::class)->decide($id,1,true,null);return $id;}
 private function professor():User{$user=User::factory()->create(['role'=>'professor','must_change_password'=>false]);DB::table('professors')->where('id',$this->f['professor'])->update(['user_id'=>$user->id]);return $user;}
 public function test_new_workspaces_render_for_their_roles():void{foreach(['/term-calendar','/students','/admission-years','/sections','/colleges','/scheduler/rooms'] as $path)$this->get($path)->assertOk();$this->actingAs($this->f['user']);foreach(['/grades','/waiting-list','/account/password'] as $path)$this->get($path)->assertOk();$this->get('/term-calendar')->assertForbidden();}
 public function test_open_requires_dates_and_automatically_assigns_sections():void{$this->post('/term-calendar/'.$this->f['period'],['action'=>'activate'])->assertSessionHasErrors('academic');DB::table('periods')->where('id',$this->f['period'])->update(['start_date'=>'2026-11-01','end_date'=>'2027-03-01']);$this->post('/term-calendar/'.$this->f['period'],['action'=>'activate'])->assertSessionHasNoErrors();$this->assertDatabaseHas('student_sections',['student_id'=>$this->f['student'],'section_id'=>$this->f['section']]);}
 public function test_full_sections_open_the_next_label_without_moving_prior_students():void{$this->open();DB::table('sections')->where('id',$this->f['section'])->update(['capacity'=>1]);$user=User::factory()->create();$student=$this->row('students',['user_id'=>$user->id,'admission_id'=>'ADM-2','curriculum_id'=>$this->f['curriculum']]);$id=app(TermWorkflowService::class)->assign($student,$this->f['period']);$this->assertDatabaseHas('sections',['id'=>$id,'name'=>'BSIT 1B']);$this->assertDatabaseHas('student_sections',['student_id'=>$this->f['student'],'section_id'=>$this->f['section']]);$this->assertSame($id,app(TermWorkflowService::class)->assign($student,$this->f['period']));}
 public function test_lock_blocks_schedule_changes_but_allows_student_acceptance():void{$this->open();DB::table('subjects')->where('id',$this->f['subject'])->update(['weekly_hours'=>1]);$this->post('/term-calendar/'.$this->f['period'],['action'=>'lock','year_level'=>1,'confirm'=>1])->assertSessionHasNoErrors();$this->post('/academic/schedules/'.$this->f['schedule'].'/deactivate')->assertSessionHasErrors('academic');$id=$this->accept();$this->assertDatabaseHas('enrollments',['id'=>$id,'status'=>'finalized']);$this->assertDatabaseCount('cor_versions',1);}
 public function test_acceptance_is_atomic_and_replay_cannot_add_a_second_cor():void{$id=$this->accept();$this->post('/enrollments/'.$id.'/decision',['version'=>1,'decision'=>'accept'])->assertSessionHasErrors('academic');$this->assertDatabaseCount('cor_versions',1);$this->assertDatabaseHas('offerings',['id'=>$this->f['offering'],'enrolled_count'=>1]);}
 public function test_closed_semester_preserves_snapshots_and_prepares_next_term():void{$this->open();$id=$this->accept();$snapshot=DB::table('cor_versions')->value('snapshot');$this->actingAs($this->f['registrar'])->post('/term-calendar/'.$this->f['period'],['action'=>'close','confirm'=>1])->assertSessionHasNoErrors();$this->assertDatabaseHas('periods',['academic_year'=>'2026-2027','semester'=>2,'is_current'=>false]);$this->assertDatabaseCount('schedules',1);$this->assertSame($snapshot,DB::table('cor_versions')->value('snapshot'));$this->post('/enrollments/'.$id.'/revise',['remarks'=>'Try closed historical revision'])->assertSessionHasErrors('academic');}
 public function test_room_booking_preview_is_read_only_and_save_enforces_weekly_hours():void{$this->open();DB::table('subjects')->where('id',$this->f['subject'])->update(['weekly_hours'=>2]);$data=['section_id'=>$this->f['section'],'subject_id'=>$this->f['subject'],'room_id'=>$this->f['room'],'professor_id'=>$this->f['professor'],'day'=>'Mon','start_time'=>'09:00','end_time'=>'10:00'];$this->postJson('/scheduler/book',$data+['preview'=>1])->assertOk();$this->assertDatabaseCount('schedules',1);$this->postJson('/scheduler/book',$data)->assertOk();$this->assertDatabaseCount('schedules',2);$data['start_time']='10:00';$data['end_time']='11:00';$this->postJson('/scheduler/book',$data)->assertUnprocessable();}
 public function test_professor_grades_only_their_finalized_roster_and_student_sees_results():void{$this->accept();$professor=$this->professor();$this->actingAs($professor)->get('/professor')->assertOk()->assertSee('IT001');$this->post('/professor/classes/'.$this->f['offering'].'/grades',['grades'=>[$this->f['student']=>'5.00']])->assertSessionHasNoErrors();$this->assertDatabaseHas('academic_records',['student_id'=>$this->f['student'],'grade'=>'5.00','status'=>'FAILED','submitted_by'=>$professor->id]);$this->assertDatabaseHas('students',['id'=>$this->f['student'],'classification'=>'irregular']);$this->get('/records')->assertForbidden();$this->get('/enrollments')->assertForbidden();$this->actingAs($this->f['user'])->get('/grades')->assertOk()->assertSee('5.00');}
 public function test_unassigned_professor_and_non_roster_grade_are_forbidden():void{$this->accept();$other=User::factory()->create(['role'=>'professor','must_change_password'=>false]);$this->actingAs($other)->post('/professor/classes/'.$this->f['offering'].'/grades',['grades'=>[$this->f['student']=>'1.00']])->assertForbidden();$this->actingAs($this->professor())->post('/professor/classes/'.$this->f['offering'].'/grades',['grades'=>[999=>'1.00']])->assertForbidden();$this->assertDatabaseCount('academic_records',0);}
 public function test_waiting_subject_releases_after_prerequisite_passes():void{$this->open();DB::table('students')->where('id',$this->f['student'])->update(['classification'=>'irregular']);$pre=$this->row('subjects',['code'=>'PRE','name'=>'Prerequisite','units'=>3]);$this->row('prerequisites',['subject_id'=>$this->f['subject'],'required_subject_id'=>$pre]);$this->actingAs($this->f['user'])->post('/waiting-list',['period_id'=>$this->f['period'],'subject_ids'=>[$this->f['subject']],'remarks'=>'Request this back subject.'])->assertSessionHasNoErrors();$this->assertDatabaseHas('subject_waiting_list',['status'=>'waiting']);$this->row('academic_records',['student_id'=>$this->f['student'],'subject_id'=>$pre,'period_id'=>$this->f['period'],'status'=>'PASSED','grade'=>'1.00']);app(WaitingListService::class)->release($this->f['period']);$this->assertDatabaseHas('subject_waiting_list',['status'=>'released']);$this->assertDatabaseHas('special_cases',['student_id'=>$this->f['student'],'status'=>'pending']);}
 public function test_promotion_requires_complete_year_grades_and_cannot_run_twice():void{DB::table('periods')->where('id',$this->f['period'])->update(['academic_year'=>'2026-2027','semester'=>2,'closed_at'=>now()]);$data=['action'=>'promote','period_id'=>$this->f['period'],'student_ids'=>[$this->f['student']],'confirm'=>1];$this->post('/students/actions',$data)->assertSessionHas('workflow_errors');$this->assertDatabaseHas('students',['id'=>$this->f['student'],'year_level'=>1]);$this->row('academic_records',['student_id'=>$this->f['student'],'subject_id'=>$this->f['subject'],'period_id'=>$this->f['period'],'status'=>'PASSED','grade'=>'2.00']);$this->post('/students/actions',$data)->assertSessionHasNoErrors();$this->assertDatabaseHas('students',['id'=>$this->f['student'],'year_level'=>2]);$this->post('/students/actions',$data)->assertSessionHas('workflow_errors');$this->assertDatabaseCount('student_promotions',1);}
 public function test_json_paste_uses_the_same_import_contract():void{$payload=['source'=>'admission','schema_version'=>'1.0','students'=>[['admission_id'=>'ADM-2026-42','first_name'=>'Import','last_name'=>'Fixture','email'=>'paste@example.test','program_code'=>'BSIT','year_level'=>1,'admission_status'=>'ADMITTED','temporary_password'=>'TemporaryPass123!']]];$this->open();$this->post('/imports',['source'=>'admission','curriculum_id'=>$this->f['curriculum'],'json'=>json_encode($payload)])->assertSessionHasNoErrors();$student=DB::table('students')->where('admission_id','ADM-2026-42')->first();$this->assertNotNull($student);$this->assertSame(2026,$student->admission_year);$this->assertDatabaseHas('student_sections',['student_id'=>$student->id,'period_id'=>$this->f['period']]);}
 public function test_semester_dates_validate_overlap_and_order():void{$id=$this->row('periods',['name'=>'Next','academic_year'=>'2026-2027','semester'=>2,'start_date'=>'2027-04-01','end_date'=>'2027-08-01']);DB::table('periods')->where('id',$this->f['period'])->update(['academic_year'=>'2026-2027']);$this->post('/term-calendar/'.$this->f['period'],['action'=>'dates','start_date'=>'2026-11-01','end_date'=>'2027-05-01'])->assertSessionHasErrors('academic');$this->post('/term-calendar/'.$this->f['period'],['action'=>'dates','start_date'=>'2026-11-01','end_date'=>'2027-03-01'])->assertSessionHasNoErrors();}
 public function test_defer_preserves_request_and_releases_when_class_becomes_available():void{$this->open();DB::table('students')->where('id',$this->f['student'])->update(['classification'=>'irregular']);DB::table('schedules')->where('id',$this->f['schedule'])->update(['active'=>false]);$case=$this->row('special_cases',['student_id'=>$this->f['student'],'period_id'=>$this->f['period'],'request'=>'Unavailable back subject','requested_subject_ids'=>json_encode([$this->f['subject']])]);$head=User::factory()->create(['role'=>'department_head','must_change_password'=>false]);$this->row('department_head_programs',['user_id'=>$head->id,'program_id'=>$this->f['program']]);$this->actingAs($head)->post('/special-cases/'.$case.'/defer',['reason'=>'Wait for the class to be scheduled.'])->assertSessionHasNoErrors();$this->assertDatabaseHas('special_cases',['id'=>$case,'status'=>'deferred']);DB::table('schedules')->where('id',$this->f['schedule'])->update(['active'=>true]);app(WaitingListService::class)->release($this->f['period']);$this->assertDatabaseHas('subject_waiting_list',['status'=>'released']);$this->assertDatabaseCount('special_cases',2);}
 public function test_professor_api_cannot_enumerate_students_or_academic_management():void{$this->accept();$professor=$this->professor();$this->actingAs($professor)->get('/activity')->assertOk()->assertDontSee($this->f['user']->name);\Laravel\Sanctum\Sanctum::actingAs($professor,['portal']);$this->getJson('/api/v1/students')->assertForbidden();$this->getJson('/api/v1/subjects')->assertForbidden();}
 public function test_closed_term_rejects_professor_grade_changes():void{$this->open();$this->accept();$professor=$this->professor();$this->actingAs($this->f['registrar']);app(TermWorkflowService::class)->close($this->f['period']);$this->actingAs($professor)->post('/professor/classes/'.$this->f['offering'].'/grades',['grades'=>[$this->f['student']=>'1.00']])->assertSessionHasErrors('academic');$this->assertDatabaseCount('academic_records',0);}
 public function test_bulk_student_assignment_does_not_require_promotion_confirmation():void{$this->open();$this->post('/students/actions',['action'=>'auto_assign','period_id'=>$this->f['period'],'student_ids'=>[$this->f['student']]])->assertSessionHasNoErrors()->assertSessionHas('status','1 student(s) updated.');}
 public function test_special_queue_renders_and_only_staged_drafts_can_be_published():void{$this->get('/special-enrollment')->assertOk();$id=app(EnrollmentService::class)->propose($this->f['student'],$this->f['period'],[$this->f['offering']]);$this->post('/special-enrollment',['enrollment_ids'=>[$id]])->assertSessionHas('workflow_errors');$this->assertDatabaseHas('enrollments',['id'=>$id,'version'=>1]);}
 public function test_closed_term_pending_proposals_do_not_block_later_record_review():void{$this->open();app(EnrollmentService::class)->propose($this->f['student'],$this->f['period'],[$this->f['offering']]);app(TermWorkflowService::class)->close($this->f['period']);$this->post('/records/'.$this->f['student'],['classification'=>'returning','year_level'=>1])->assertSessionHasNoErrors();$this->assertDatabaseHas('enrollments',['student_id'=>$this->f['student'],'status'=>'term_closed']);}
 public function test_promotion_refreshes_an_unpublished_next_year_membership():void{$this->open();DB::table('periods')->where('id',$this->f['period'])->update(['semester'=>2]);$next=app(TermWorkflowService::class)->close($this->f['period']);DB::table('periods')->where('id',$next)->update(['start_date'=>'2027-11-01','end_date'=>'2028-03-01']);app(TermWorkflowService::class)->activate($next);$this->row('academic_records',['student_id'=>$this->f['student'],'subject_id'=>$this->f['subject'],'period_id'=>$this->f['period'],'status'=>'PASSED','grade'=>'1.00']);app(TermWorkflowService::class)->promote($this->f['student'],$this->f['period']);$membership=DB::table('student_sections')->where(['student_id'=>$this->f['student'],'period_id'=>$next])->first();$this->assertDatabaseHas('sections',['id'=>$membership->section_id,'year_level'=>2]);$this->assertDatabaseHas('student_sections',['student_id'=>$this->f['student'],'period_id'=>$this->f['period'],'section_id'=>$this->f['section']]);$this->get('/students?period_id='.$this->f['period'])->assertOk()->assertViewHas('students',fn($rows)=>$rows->first()->year_level===1);}
 public function test_approved_head_builder_renders_and_closed_case_cannot_be_evaluated():void{$this->open();DB::table('students')->where('id',$this->f['student'])->update(['classification'=>'irregular']);$head=User::factory()->create(['role'=>'department_head','must_change_password'=>false]);$this->row('department_head_programs',['user_id'=>$head->id,'program_id'=>$this->f['program']]);$case=$this->row('special_cases',['student_id'=>$this->f['student'],'period_id'=>$this->f['period'],'status'=>'approved','request'=>'Review requested subject','requested_subject_ids'=>json_encode([$this->f['subject']])]);$this->actingAs($head)->get('/special-cases/'.$case)->assertOk()->assertSee('Build the proposed schedule')->assertSee('Assignment preview');DB::table('special_cases')->where('id',$case)->update(['status'=>'pending']);$this->actingAs($this->f['registrar']);app(TermWorkflowService::class)->close($this->f['period']);$this->actingAs($head)->post('/special-cases/'.$case.'/evaluate',['status'=>'approved','evaluation'=>'Attempt to evaluate a closed semester'])->assertSessionHasErrors('academic');}
}
